const ELEMENT_PROP_KEYS = new Set(["theme","label","before","after","unit","verdict","shape","beforeValue","afterValue","shrink","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "Bundle size",
